code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            colors = {grid[y][x] for y, x in cells}
            if len(colors) < 2:
                continue
            bounds = {}
            for color in colors:
                positions = [(y,x) for y,x in cells if grid[y][x] == color]
                bounds[color] = (max(y for y,x in positions)-min(y for y,x in positions)+1) * (max(x for y,x in positions)-min(x for y,x in positions)+1)
            outer_to_inner = sorted(colors, key=lambda color: bounds[color], reverse=True)
            remap = {color: outer_to_inner[-1-i] for i,color in enumerate(outer_to_inner)}
            for y, x in cells:
                out[y][x] = remap[grid[y][x]]
    return out
'''
